141	    --text-3: #6d6684;
142	    --text-inv: #0a0918;
143	
144	    --brand: #ff5c97;
145	    --brand-hover: #ff7aab;
146	    --brand-tint: rgba(255, 92, 151, 0.12);
147	    --brand-tint-2: rgba(255, 92, 151, 0.2);
148	    --brand-ring: rgba(255, 92, 151, 0.45);
149	    --brand-ink: #ffd0e0;
150	
151	    --ok: #34d399;
152	    --ok-tint: rgba(52, 211, 153, 0.14);
153	    --warn: #fbbf5a;
154	    --warn-tint: rgba(251, 191, 90, 0.14);
155	    --danger: #ff7080;
156	    --danger-tint: rgba(255, 112, 128, 0.14);
157	    --info: #9b8cff;
158	    --info-tint: rgba(155, 140, 255, 0.14);
159	
160	    --e1: 0 1px 2px rgba(0, 0, 0, 0.5);
161	    --e2: 0 1px 2px rgba(0, 0, 0, 0.5), 0 10px 24px -14px rgba(0, 0, 0, 0.8);
162	    --e3: 0 2px 6px rgba(0, 0, 0, 0.55), 0 28px 56px -26px rgba(0, 0, 0, 0.9);
163	  }
164	}
