302	/* Ambient background — one very slow, very soft light behind every
303	   marketing page. Fixed, never scrolls, never shifts color — the motion
304	   budget is spent on foreground elements, not this. */
305	.aura {
306	  position: fixed;
307	  inset: 0;
308	  z-index: 0;
309	  pointer-events: none;
310	  overflow: hidden;
311	}
312	.aura b {
313	  position: absolute;
314	  border-radius: 50%;
315	  filter: blur(120px);
316	  opacity: 0.6;
317	}
318	.aura .a1 {
319	  width: 52vw;
320	  height: 52vw;
321	  left: -8vw;
322	  top: -14vw;
323	  background: radial-gradient(closest-side, var(--glow), transparent);
324	}
325	.aura .a2 {
326	  width: 46vw;
327	  height: 46vw;
328	  right: -10vw;
329	  bottom: -4vw;
330	  background: radial-gradient(closest-side, var(--glow-2), transparent);
331	}
332	
333	/* The prompt-box glow ring (PromptHero) — a Gemini-style "chasing light"
334	   ring, rebuilt using only decade-old, maximally-compatible CSS: plain
335	   `transform: rotate()` and `overflow: hidden` clipping. No @property, no
336	   CSS masking — both were dropped after repeated reports that the effect
337	   still wasn't appearing correctly even in a fresh browser with a verified
338	   non-cached, up-to-date stylesheet, which means the earlier @property +
339	   mask-composite combination (both comparatively modern CSS features) was
340	   the most likely remaining suspect, even though I could not get direct
341	   visual confirmation either way in this environment.
342	
343	   The technique: each layer is a STATIC outer clipper
344	   (`.glow-clip-a/-b`, position:absolute, overflow:hidden, never
345	   transforms) containing one OVERSIZED inner rotator
346	   (`.glow-spin-a/-b`, ~2x the clipper's size, centered via inset:-50%).
347	   Only the inner rotator spins via plain `transform: rotate()` — since
348	   it's oversized, its corners sweeping outside a same-sized box (the
349	   original "wide rectangle rotated as a rigid body" bug) never matters:
350	   they're clipped away by the static outer box at every angle. The
351	   composer sitting on top (z-10, opaque) covers the rotator's entire
352	   interior, leaving only the outer few px visible as a ring — no masking
353	   needed for that either. */
354	@keyframes glow-spin {
355	  to {
356	    transform: rotate(360deg);
357	  }
358	}
359	.glow-spin-a {
360	  animation: glow-spin 9s linear infinite;
361	}
362	.glow-spin-b {
363	  animation: glow-spin 14s linear infinite reverse;
364	}
365	
366	/* Entrance fade-in — plain CSS on the static outer clipper, not a
367	   framer-motion `whileInView` (depends on IntersectionObserver + React
368	   state + framer's scheduling — more moving parts than necessary here).
369	   `forwards` is load-bearing: without it, the element snaps back to its
370	   non-animated base style the instant the single iteration ends. */
371	@keyframes glow-fade-in-a {
372	  from {
373	    opacity: 0;
374	    transform: scale(0.94);
375	  }
376	  to {
377	    opacity: 0.35;
378	    transform: scale(1);
379	  }
380	}
381	@keyframes glow-fade-in-b {
382	  from {
383	    opacity: 0;
384	    transform: scale(0.94);
385	  }
386	  to {
387	    opacity: 0.2;
388	    transform: scale(1);
389	  }
390	}
391	
392	/* Ambient pulse — a slow breathe, kept subtle so it reads as the glow
393	   "living" rather than blinking. Runs as a THIRD animation chained after
394	   the entrance: the fade-in owns opacity for its first 0.8s, then this
395	   takes over from the same value it settled on (0.35 / 0.2), so there is
396	   no jump at the handoff — keep the two in sync when retuning intensity.
397	   Its delay must match the fade-in's duration.
398	   The floor never approaches 0 — the glow dims and brightens, it never
399	   disappears. */
400	@keyframes glow-pulse-a {
401	  0%,
402	  100% {
403	    opacity: 0.35;
404	  }
405	  50% {
406	    opacity: 0.5;
407	  }
408	}
409	@keyframes glow-pulse-b {
410	  0%,
411	  100% {
412	    opacity: 0.2;
413	  }
414	  50% {
415	    opacity: 0.33;
416	  }
417	}
418	.glow-clip-a {
419	  animation:
420	    glow-fade-in-a 0.8s cubic-bezier(0.16, 1, 0.3, 1) both,
421	    glow-pulse-a 4.5s ease-in-out 0.8s infinite;
422	}
423	.glow-clip-b {
424	  animation:
425	    glow-fade-in-b 0.9s cubic-bezier(0.16, 1, 0.3, 1) 0.1s both,
426	    glow-pulse-b 6s ease-in-out 1s infinite;
427	}
428	
429	/* Scroll entrance for the hero mock (HeroMock.tsx). A CSS transition
430	   toggled by an `is-entered` class from an IntersectionObserver — no
431	   dependence on framer-motion's in-view scheduling, which applied its
432	   initial styles here but never actually triggered. */
433	@keyframes hero-mock-in {
434	  from {
435	    opacity: 0;
436	    transform: translateY(56px) scale(0.94);
437	  }
438	  to {
439	    opacity: 1;
440	    transform: translateY(0) scale(1);
441	  }
442	}
443	
444	/* Fallback for browsers without scroll-driven animation support: play the
445	   entrance once on load. Not as nice as scroll-linked, but never leaves
446	   the mock stuck invisible. */
447	.hero-mock-enter {
448	  animation: hero-mock-in 0.9s cubic-bezier(0.16, 1, 0.3, 1) both;
449	}
450	
451	/* The real thing: a native scroll-driven animation, progressed by the
452	   element's own position in the viewport. No IntersectionObserver, no
453	   scroll listener, no React state — every JS-based trigger tried here
454	   (framer's whileInView, a raw IntersectionObserver, a scroll listener)
455	   failed to fire in practice, and this removes that entire class of
456	   failure. `view()` ties progress to the element crossing the viewport;
457	   the range runs from just after it appears to a third of the way up, so
458	   it finishes as you arrive at it rather than while it's still an
459	   off-screen sliver. */
460	@supports (animation-timeline: view()) {
461	  .hero-mock-enter {
462	    /* Longhands, not the `animation` shorthand: the shorthand defaults
463	       animation-duration to 0s when it's omitted, which — combined with
464	       fill:both — snapped straight to the end state at every scroll
465	       position (i.e. no visible animation at all). Scroll-driven
466	       animations need `auto`, which maps progress onto animation-range.
467	       The shorthand also resets animation-timeline, so setting these
468	       individually keeps the two declarations from fighting. */
469	    animation-name: hero-mock-in;
470	    animation-duration: auto;
471	    animation-timing-function: linear;
472	    animation-fill-mode: both;
473	    animation-timeline: view();
474	    /* Spans the element's whole entry into the viewport: starts just after
475	       its top edge appears and finishes exactly when it's fully on screen.
476	       Both endpoints in the same phase keeps it predictable (an earlier
477	       `entry 15% cover 38%` mixed phases, which is legal but harder to
478	       reason about and compressed the motion into a shorter scroll). */
479	    animation-range: entry 10% entry 100%;
480	  }
481	}
482	
483	@keyframes marquee {
484	  from {
485	    transform: translateX(0);
486	  }
487	  to {
488	    transform: translateX(-50%);
489	  }
490	}
491	
492	/* ── Build-in-progress treatment (app/projects/[id]/BuildingOverlay.tsx) ──
493	   The Kodely mark breathes while a build runs. Scale only, and only 3% —
494	   enough to read as alive, small enough not to look like a loading spinner
495	   fighting for attention. */
496	@keyframes kodely-breathe {
497	  0%,
498	  100% {
499	    transform: scale(1);
500	  }
501	  50% {
502	    transform: scale(1.03);
503	  }
504	}
505	.kodely-breathe {
506	  animation: kodely-breathe 2.4s ease-in-out infinite;
507	}
508	
509	/* Skeleton blocks: fade up into place once (staggered by inline delay), then
510	   a highlight sweeps across them continuously. `background-position` rather
511	   than a moving pseudo-element so there is nothing to clip or overflow. */
512	@keyframes kodely-skeleton-in {
513	  from {
514	    opacity: 0;
515	    transform: translateY(6px);
516	  }
517	  to {
518	    opacity: 1;
519	    transform: translateY(0);
520	  }
521	}
522	@keyframes kodely-skeleton-sweep {
523	  from {
524	    background-position: 200% 0;
525	  }
526	  to {
527	    background-position: -200% 0;
528	  }
529	}
530	.kodely-skeleton {
531	  opacity: 0;
532	  background-color: color-mix(in oklab, currentColor 8%, transparent);
533	  background-image: linear-gradient(
534	    90deg,
535	    transparent 20%,
