826	
827	/* Ambient brand wash for hero panels inside the product (dashboard welcome,
828	   create-website prompt). Softer than the marketing .aura and NOT fixed —
829	   it belongs to its panel and scrolls with it. */
830	.k-wash {
831	  position: absolute;
832	  inset: 0;
833	  pointer-events: none;
834	  overflow: hidden;
835	  border-radius: inherit;
836	}
837	.k-wash::before,
838	.k-wash::after {
