855	  bottom: -50%;
856	  background: radial-gradient(closest-side, var(--glow-2), transparent);
857	}
858	
859	/* Sidebar collapse. The width lives on the shell as a custom property so the
860	   sidebar, the mobile drawer and the main column all animate off one value
