4	
5	export type ButtonVariant = "primary" | "secondary" | "ghost" | "soft" | "danger";
6	export type ButtonSize = "xs" | "sm" | "md" | "lg";
7	
8	/* One button, five variants, and a hard rule: exactly ONE primary per view.
9	   The old portal had four visually identical links in its header and no
10	   obvious next action, which is most of why it read as generic. */
11	const VARIANT: Record<ButtonVariant, string> = {
12	  // The only element in the product that carries the brand gradient as a
13	  // fill. `group` + the two .btn-* classes reuse the marketing CTA treatment
14	  // verbatim so the "Create Website" button feels like the same object the
15	  // customer clicked on the marketing site.
16	  primary:
17	    "group relative overflow-hidden text-white btn-cta-gradient shadow-e2 hover:shadow-e3 active:translate-y-px",
18	  secondary:
19	    "bg-surface text-ink border border-line-mid hover:bg-surface-2 hover:border-line-strong shadow-e1",
20	  ghost: "text-ink-2 hover:bg-surface-2 hover:text-ink",
21	  soft: "bg-brand-tint text-brand-ink hover:bg-brand-tint-2 dark:text-brand",
22	  danger: "bg-danger-tint text-danger hover:brightness-95 dark:hover:brightness-110",
23	};
24	
25	const SIZE: Record<ButtonSize, string> = {
26	  xs: "h-7 gap-1.5 px-2.5 text-xs rounded-sm",
27	  sm: "h-8 gap-1.5 px-3 text-[0.8125rem] rounded-md",
28	  md: "h-9.5 gap-2 px-4 text-sm rounded-md",
29	  lg: "h-11.5 gap-2 px-5 text-[0.9375rem] rounded-lg",
30	};
31	
32	export function buttonClass({
33	  variant = "secondary",
34	  size = "md",
35	  block = false,
36	  className = "",
37	}: {
38	  variant?: ButtonVariant;
39	  size?: ButtonSize;
40	  block?: boolean;
41	  className?: string;
42	} = {}) {
43	  return [
44	    "k-focus inline-flex select-none items-center justify-center whitespace-nowrap font-medium",
45	    "transition-[background,color,box-shadow,border-color,transform] duration-[var(--t-1)]",
46	    "disabled:pointer-events-none disabled:opacity-45",
47	    SIZE[size],
48	    VARIANT[variant],
49	    block ? "w-full" : "",
50	    className,
51	  ]
52	    .filter(Boolean)
53	    .join(" ");
54	}
55	
56	/** The gradient variant needs a sheen element inside it; nothing else does. */
57	function Shine({ variant }: { variant: ButtonVariant }) {
58	  if (variant !== "primary") return null;
59	  return (
60	    <span
61	      aria-hidden
62	      className="btn-shine pointer-events-none absolute top-0 left-[-40%] h-full w-[35%] skew-x-[-20deg] bg-white/25"
63	    />
64	  );
65	}
66	
67	type BaseProps = {
68	  variant?: ButtonVariant;
69	  size?: ButtonSize;
70	  block?: boolean;
71	  /** Shows a spinner in place of `icon`, sets aria-busy, and disables. */
72	  loading?: boolean;
73	  icon?: ReactNode;
74	  iconRight?: ReactNode;
75	  children?: ReactNode;
76	};
77	
78	export function Button({
79	  variant = "secondary",
80	  size = "md",
81	  block,
82	  loading = false,
83	  icon,
84	  iconRight,
85	  className,
86	  children,
87	  disabled,
88	  ...rest
89	}: BaseProps & Omit<ComponentProps<"button">, "children">) {
90	  return (
91	    <button
92	      {...rest}
93	      disabled={disabled || loading}
94	      aria-busy={loading || undefined}
95	      className={buttonClass({ variant, size, block, className })}
96	    >
97	      <Shine variant={variant} />
98	      {/* The icon slot keeps its box while loading so the label never shifts
99	          sideways at the moment the customer clicks. */}
100	      {loading ? <Spinner size={size === "lg" ? 16 : 14} /> : icon}
101	      {children != null && <span className="relative">{children}</span>}
102	      {!loading && iconRight}
103	    </button>
104	  );
105	}
106	
107	export function ButtonLink({
108	  variant = "secondary",
109	  size = "md",
110	  block,
111	  icon,
112	  iconRight,
113	  className,
114	  children,
115	  ...rest
116	}: BaseProps & Omit<ComponentProps<typeof Link>, "children">) {
117	  return (
118	    <Link {...rest} className={buttonClass({ variant, size, block, className })}>
119	      <Shine variant={variant} />
120	      {icon}
121	      {children != null && <span className="relative">{children}</span>}
122	      {iconRight}
123	    </Link>
124	  );
125	}
126	
127	/** Square icon-only button. Requires a label — an unlabelled icon button is
128	    invisible to a screen reader and, collapsed in the sidebar, to everyone. */
129	export function IconButton({
130	  label,
131	  variant = "ghost",
132	  size = "md",
133	  className = "",
134	  children,
135	  ...rest
136	}: {
137	  label: string;
138	  variant?: ButtonVariant;
139	  size?: ButtonSize;
140	} & Omit<ComponentProps<"button">, "children"> & { children: ReactNode }) {
141	  const square = { xs: "size-7", sm: "size-8", md: "size-9.5", lg: "size-11.5" }[size];
142	  return (
143	    <button
144	      {...rest}
145	      aria-label={label}
146	      title={label}
147	      className={buttonClass({
148	        variant,
149	        size,
150	        className: `!px-0 ${square} ${className}`,
151	      })}
152	    >
153	      {children}
154	    </button>
155	  );
156	}
