34	  trigger,
35	  items,
36	  align = "end",
37	  className = "",
38	}: {
39	  trigger: (props: {
40	    ref: React.Ref<HTMLButtonElement>;
41	    onClick: () => void;
42	    "aria-expanded": boolean;
43	    "aria-haspopup": "menu";
44	    "aria-controls": string;
45	  }) => ReactNode;
46	  items: MenuItem[];
47	  align?: "start" | "end";
48	  className?: string;
49	}) {
50	  const [open, setOpen] = useState(false);
51	  const id = useId();
52	  const triggerRef = useRef<HTMLButtonElement>(null);
53	  const listRef = useRef<HTMLDivElement>(null);
54	
55	  useEffect(() => {
56	    if (!open) return;
57	
58	    // pointerdown, not click: a click listener fires after the target's own
59	    // handler, so clicking a second menu's trigger would open it and then this
60	    // would close nothing useful, leaving both states out of step.
61	    const onPointerDown = (e: PointerEvent) => {
62	      const t = e.target as Node;
63	      if (listRef.current?.contains(t) || triggerRef.current?.contains(t)) return;
64	      setOpen(false);
65	    };
66	    const onKey = (e: KeyboardEvent) => {
67	      if (e.key === "Escape") {
68	        setOpen(false);
69	        triggerRef.current?.focus();
70	      }
71	    };
72	    document.addEventListener("pointerdown", onPointerDown);
73	    document.addEventListener("keydown", onKey);
74	    // Move focus into the menu so the keyboard path works from the first press.
75	    listRef.current?.querySelector<HTMLElement>("[data-menu-item]")?.focus();
