86	    if (focusable.length === 0) return;
87	    const i = focusable.indexOf(document.activeElement as HTMLElement);
88	    const go = (n: number) => {
89	      e.preventDefault();
90	      focusable[(n + focusable.length) % focusable.length]?.focus();
91	    };
92	    if (e.key === "ArrowDown") go(i + 1);
93	    else if (e.key === "ArrowUp") go(i - 1);
94	    else if (e.key === "Home") go(0);
95	    else if (e.key === "End") go(focusable.length - 1);
96	  };
