99	    <div className={`relative ${className}`}>
100	      {trigger({
101	        ref: triggerRef,
102	        onClick: () => setOpen((v) => !v),
103	        "aria-expanded": open,
104	        "aria-haspopup": "menu",
105	        "aria-controls": id,
106	      })}
