108	        <div
109	          ref={listRef}
110	          id={id}
111	          role="menu"
112	          onKeyDown={onListKeyDown}
113	          className={[
114	            "k-msg-in absolute z-50 mt-1.5 min-w-52 overflow-hidden rounded-lg border border-line-mid",
115	            "bg-surface p-1 shadow-e3",
116	            align === "end" ? "right-0" : "left-0",
117	          ].join(" ")}
118	        >
119	          {items.map((item, idx) => {
120	            if (item.kind === "separator") {
121	              return <div key={idx} role="separator" className="my-1 h-px bg-hair" />;
122	            }
123	            if (item.kind === "label") {
124	              return (
125	                <div key={idx} className="k-label px-2.5 pt-2 pb-1.5">
126	                  {item.label}
127	                </div>
128	              );
129	            }
130	            const blocked = item.disabled || item.unavailableReason != null;
131	            const cls = [
132	              "k-focus flex w-full items-center gap-2.5 rounded-md px-2.5 py-1.5 text-left text-[0.8125rem]",
133	              blocked
134	                ? "cursor-not-allowed text-ink-3"
135	                : item.danger
136	                  ? "text-danger hover:bg-danger-tint"
137	                  : "text-ink hover:bg-surface-2",
138	            ].join(" ");
139	            const body = (
140	              <>
141	                {item.icon != null && <span className="shrink-0 text-ink-3">{item.icon}</span>}
142	                <span className="flex-1 truncate">{item.label}</span>
143	                {item.unavailableReason != null && (
144	                  <span className="shrink-0 text-[0.6875rem] text-ink-3">
145	                    {item.unavailableReason}
146	                  </span>
147	                )}
148	              </>
149	            );
150	            if (item.href != null && !blocked) {
151	              return (
152	                <Link
153	                  key={idx}
154	                  href={item.href}
155	                  role="menuitem"
156	                  data-menu-item
157	                  className={cls}
158	                  onClick={() => setOpen(false)}
159	                >
160	                  {body}
161	                </Link>
162	              );
163	            }
164	            return (
165	              <button
166	                key={idx}
167	                type="button"
168	                role="menuitem"
169	                data-menu-item
170	                aria-disabled={blocked || undefined}
171	                className={cls}
172	                onClick={() => {
173	                  if (blocked) return;
174	                  setOpen(false);
175	                  item.onSelect?.();
176	                }}
177	              >
178	                {body}
179	              </button>
180	            );
181	          })}
182	        </div>
183	      )}
184	    </div>
185	  );
186	}
