15	  description,
16	  children,
17	  footer,
18	  size = "md",
19	}: {
20	  open: boolean;
21	  onClose: () => void;
22	  title: string;
23	  description?: ReactNode;
24	  children?: ReactNode;
25	  footer?: ReactNode;
26	  size?: "sm" | "md" | "lg";
27	}) {
28	  const ref = useRef<HTMLDialogElement>(null);
29	
30	  useEffect(() => {
31	    const el = ref.current;
32	    if (!el) return;
33	    // Guard both directions: calling showModal() on an already-open dialog
34	    // throws InvalidStateError, and close() on a closed one fires a spurious
35	    // cancel/close event that would call onClose in a loop.
36	    if (open && !el.open) el.showModal();
37	    if (!open && el.open) el.close();
38	  }, [open]);
39	
40	  const width = { sm: "max-w-sm", md: "max-w-lg", lg: "max-w-2xl" }[size];
41	
42	  return (
43	    <dialog
44	      ref={ref}
45	      // `cancel` is Escape. Prevented and routed through onClose so the parent
46	      // stays the single owner of `open` — otherwise the dialog closes itself
47	      // and React re-opens it on the next render.
48	      onCancel={(e) => {
49	        e.preventDefault();
50	        onClose();
51	      }}
52	      onClose={onClose}
