54	      // anything inside targets a descendant. That distinction is the whole
55	      // click-outside implementation.
56	      onClick={(e) => {
57	        if (e.target === ref.current) onClose();
58	      }}
59	      className={`m-auto w-[calc(100vw-2rem)] ${width} rounded-xl border border-line-mid bg-surface p-0 text-ink shadow-e3 backdrop:bg-black/45 backdrop:backdrop-blur-sm`}
60	    >
61	      <div className="flex items-start justify-between gap-4 px-5 pt-5">
62	        <div className="min-w-0">
63	          <h2 className="k-h2 text-ink">{title}</h2>
64	          {description != null && (
