66	          )}
67	        </div>
68	        <IconButton label="Close" size="sm" onClick={onClose}>
69	          <svg viewBox="0 0 24 24" className="size-4" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
70	            <path d="m6 6 12 12M18 6 6 18" />
71	          </svg>
72	        </IconButton>
73	      </div>
74	      {children != null && <div className="px-5 py-4 text-sm text-ink-2">{children}</div>}
75	      {footer != null && (
76	        <div className="flex justify-end gap-2 border-t border-hair bg-surface-2/50 px-5 py-3.5">
