20	export function Progress({
21	  value,
22	  max = 100,
23	  tone,
24	  size = "md",
25	  indeterminate = false,
26	  label,
27	  className = "",
28	}: {
29	  value: number;
30	  max?: number;
31	  tone?: Tone;
32	  size?: "sm" | "md";
33	  /** For work with no measurable end — a build in flight. */
34	  indeterminate?: boolean;
35	  /** Accessible name. Required whenever the bar is not adjacent to its own
36	      caption, which is most of the time. */
37	  label?: string;
38	  className?: string;
39	}) {
40	  // Guard the denominator before it reaches a style attribute: a NaN width is
41	  // silently dropped by the browser and the bar renders permanently empty,
42	  // which reads as "you have used nothing" rather than as a bug.
43	  const safeMax = max > 0 ? max : 1;
44	  const pct = Math.max(0, Math.min(100, (value / safeMax) * 100));
45	  const resolved = tone ?? toneForUsage(pct / 100);
46	
47	  return (
48	    <div
49	      role="progressbar"
50	      aria-label={label}
51	      aria-valuenow={indeterminate ? undefined : Math.round(pct)}
52	      aria-valuemin={0}
53	      aria-valuemax={100}
54	      className={`w-full overflow-hidden rounded-full bg-surface-3 ${size === "sm" ? "h-1" : "h-2"} ${className}`}
55	    >
56	      {indeterminate ? (
57	        <div className="k-indeterminate h-full w-full rounded-full" />
58	      ) : (
59	        <div
60	          className={`h-full rounded-full transition-[width,background-color] duration-[var(--t-3)] ease-[var(--ease)] ${FILL[resolved]}`}
61	          style={{ width: `${pct}%` }}
62	        />
63	      )}
64	    </div>
65	  );
66	}
