3	import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from "react";
4	import type { ReactNode } from "react";
5	
6	type ToastTone = "ok" | "danger" | "info";
7	type Toast = { id: number; tone: ToastTone; message: string; action?: { label: string; onClick: () => void } };
8	
9	const ToastContext = createContext<((t: Omit<Toast, "id">) => void) | null>(null);
10	
11	/** Throws rather than no-oping if the provider is missing: a toast that
12	    silently fails to appear turns "your site was deleted" into no feedback at
13	    all, which is worse than a crash in development. */
14	export function useToast() {
15	  const push = useContext(ToastContext);
16	  if (!push) throw new Error("useToast must be used inside <ToastProvider>");
17	  return push;
18	}
19	
20	const ICON: Record<ToastTone, ReactNode> = {
21	  ok: (
22	    <svg viewBox="0 0 24 24" className="size-4 text-ok" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
23	      <path d="m4 12.5 5 5L20 7" />
24	    </svg>
25	  ),
26	  danger: (
27	    <svg viewBox="0 0 24 24" className="size-4 text-danger" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
28	      <path d="M12 7v6M12 17v.01" />
29	      <circle cx="12" cy="12" r="9" strokeWidth="2" />
30	    </svg>
31	  ),
32	  info: (
33	    <svg viewBox="0 0 24 24" className="size-4 text-info" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
34	      <path d="M12 11v6M12 7v.01" />
35	      <circle cx="12" cy="12" r="9" strokeWidth="2" />
36	    </svg>
37	  ),
38	};
39	
40	export function ToastProvider({ children }: { children: ReactNode }) {
41	  const [toasts, setToasts] = useState<Toast[]>([]);
42	  const seq = useRef(0);
43	  const timers = useRef(new Map<number, ReturnType<typeof setTimeout>>());
44	
45	  const dismiss = useCallback((id: number) => {
46	    setToasts((list) => list.filter((t) => t.id !== id));
47	    const timer = timers.current.get(id);
48	    if (timer) {
49	      clearTimeout(timer);
50	      timers.current.delete(id);
51	    }
52	  }, []);
53	
54	  const push = useCallback(
55	    (t: Omit<Toast, "id">) => {
56	      const id = ++seq.current;
57	      setToasts((list) => [...list, { ...t, id }]);
58	      // Errors and toasts carrying an action stay put. An auto-dismissing
59	      // "Undo" is a control the customer can lose the race against.
60	      if (t.tone !== "danger" && t.action == null) {
61	        timers.current.set(id, setTimeout(() => dismiss(id), 4200));
62	      }
63	    },
64	    [dismiss],
65	  );
66	
67	  // Clearing on unmount matters in the builder, which mounts and unmounts
68	  // panels while a build is in flight. The ref is read INSIDE the effect —
69	  // reading `.current` during render is what the refs lint rule forbids, and
70	  // it would also capture a stale map if the provider ever remounted.
71	  useEffect(() => {
72	    const pending = timers.current;
73	    return () => pending.forEach(clearTimeout);
74	  }, []);
75	
76	  const value = useMemo(() => push, [push]);
77	
78	  return (
79	    <ToastContext.Provider value={value}>
80	      {children}
81	      <div
82	        // polite, not assertive: a toast reports a completed action and should
83	        // wait for the screen reader to finish what it is saying.
84	        aria-live="polite"
85	        className="pointer-events-none fixed inset-x-0 bottom-0 z-[100] flex flex-col items-center gap-2 p-4 sm:items-end"
86	      >
87	        {toasts.map((t) => (
88	          <div
89	            key={t.id}
90	            className="k-msg-in pointer-events-auto flex w-full max-w-sm items-start gap-3 rounded-lg border border-line-mid bg-surface p-3 shadow-e3"
91	          >
92	            <span className="mt-0.5 shrink-0">{ICON[t.tone]}</span>
93	            <p className="flex-1 text-[0.8125rem] leading-snug text-ink">{t.message}</p>
94	            {t.action != null && (
95	              <button
96	                type="button"
97	                className="k-focus shrink-0 rounded-sm text-[0.8125rem] font-medium text-brand hover:underline"
98	                onClick={() => {
99	                  t.action?.onClick();
100	                  dismiss(t.id);
101	                }}
102	              >
103	                {t.action.label}
104	              </button>
105	            )}
106	            <button
107	              type="button"
108	              aria-label="Dismiss"
109	              className="k-focus -m-1 shrink-0 rounded-sm p-1 text-ink-3 hover:text-ink"
110	              onClick={() => dismiss(t.id)}
111	            >
112	              <svg viewBox="0 0 24 24" className="size-3.5" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
113	                <path d="m6 6 12 12M18 6 6 18" />
114	              </svg>
115	            </button>
116	          </div>
117	        ))}
118	      </div>
119	    </ToastContext.Provider>
120	  );
121	}
