30	export default function ProjectRow({ project }: { project: ProjectRowProject }) {
31	  const router = useRouter();
32	
33	  const [mode, setMode] = useState<Mode>("idle");
34	  const [menuOpen, setMenuOpen] = useState(false);
35	  const [busy, setBusy] = useState(false);
36	  const [error, setError] = useState<string | null>(null);
