51	  useEffect(() => {
52	    if (!menuOpen) return;
53	    function onPointerDown(e: MouseEvent) {
54	      const t = e.target as Node;
55	      if (menuRef.current?.contains(t) || triggerRef.current?.contains(t)) return;
56	      setMenuOpen(false);
57	    }
58	    function onKeyDown(e: KeyboardEvent) {
59	      if (e.key === "Escape") {
60	        e.stopPropagation();
61	        closeMenu(true);
62	      }
63	    }
64	    document.addEventListener("mousedown", onPointerDown);
65	    document.addEventListener("keydown", onKeyDown);
66	    return () => {
67	      document.removeEventListener("mousedown", onPointerDown);
68	      document.removeEventListener("keydown", onKeyDown);
69	    };
70	  }, [menuOpen, closeMenu]);
