78	    const items = itemRefs.current.filter(Boolean) as HTMLButtonElement[];
79	    if (items.length === 0) return;
80	    const current = items.indexOf(document.activeElement as HTMLButtonElement);
81	    if (e.key === "ArrowDown" || e.key === "ArrowUp") {
82	      e.preventDefault();
83	      const delta = e.key === "ArrowDown" ? 1 : -1;
84	      const next = (current + delta + items.length) % items.length;
85	      items[next]?.focus();
86	    } else if (e.key === "Home") {
87	      e.preventDefault();
88	      items[0]?.focus();
89	    } else if (e.key === "End") {
90	      e.preventDefault();
