109	  const trimmed = draftName.trim();
110	  const renameDirty = trimmed.length > 0 && trimmed !== project.name;
111	
112	  function saveRename() {
113	    if (!renameDirty) {
114	      setMode("idle");
115	      return;
116	    }
117	    void run(async () => {
118	      await api(`/api/projects/${project.id}`, {
119	        method: "PATCH",
120	        body: JSON.stringify({ name: trimmed }),
121	      });
122	      setMode("idle");
123	      router.refresh();
124	    });
125	  }
126	
127	  function duplicate() {
128	    closeMenu();
129	    void run(async () => {
130	      await api(`/api/projects/${project.id}`, { method: "POST" });
