132	    });
133	  }
134	
135	  // Published sites require typing the exact name: deleting one takes a public
136	  // URL offline, and that is not something to lose to a mis-click. Drafts get
137	  // the lighter explicit two-step — the whole point of delete is clearing out
138	  // junk first attempts, and a name-typing gate on every throwaway draft would
139	  // just train people to type it without reading.
140	  const requireTypedName = project.published;
141	  const canDelete = !requireTypedName || confirmText.trim() === project.name;
142	
