1	import { db } from "./db";
2	import { MODEL_RATES } from "./models";
3	
4	// ── The anti-bill-shock contract ──────────────────────────────────────────
5	// 1. A credit is a fixed, published amount of real model spend. No mystery units.
6	// 2. We charge from METERED tokens after a build succeeds — never a flat guess.
7	// 3. A build that fails is recorded with its true cost and charged ZERO.
8	// 4. We never bill for the AI's own mistake. When a build does not compile and
9	//    the model has to repair its own broken output, the repair pass is
10	//    recorded at its true cost and charged ZERO. See settleBuild below.
11	// This is Kodely's clearest wedge against the category (see the board's
12	// "credit bill-shock" differentiation cards), so it lives in one small module.
13	
14	/** One credit = $0.002 of underlying model spend (500 credits = $1). */
15	export const MICROS_PER_CREDIT = 2_000;
16	
17	/**
18	 * New accounts start with enough to build and iterate on a real page.
19	 * Sized from measured real costs (2026-08-17): a full first build runs
20	 * ~$0.29 (144 credits), a follow-up edit ~$0.34 (172 credits) on Sonnet 5 —
21	 * 750 covers roughly one build plus 2-3 real edits.
22	 */
23	export const SIGNUP_GRANT = 750;
24	
25	export type Usage = {
26	  inputTokens: number;
27	  outputTokens: number;
28	  cacheReadTokens: number;
29	  cacheWriteTokens: number;
30	};
31	
32	/**
33	 * Micro-dollars of real model spend for a given usage on a given model.
34	 * MODEL_RATES stores USD per MILLION tokens, which — numerically — is
35	 * already USD-per-token expressed in micro-dollars (1e-6 USD = 1 microUSD).
36	 * So `rate * tokens` IS the cost in micros directly; do NOT also divide by
37	 * 1e6, that computes cost in whole dollars instead and silently floors every
38	 * build under $0.50 to 0 (which is exactly the bug this comment replaced —
39	 * caught 2026-08-17 when a real ~$0.22 build was charged only 1 credit).
40	 */
41	export function costMicros(model: string, usage: Usage): number {
42	  const rate = MODEL_RATES[model] ?? MODEL_RATES.default;
43	  const perToken = (perMTok: number, tokens: number) => perMTok * tokens;
44	  return Math.round(
45	    perToken(rate.input, usage.inputTokens) +
46	      perToken(rate.output, usage.outputTokens) +
47	      perToken(rate.cacheRead, usage.cacheReadTokens) +
48	      perToken(rate.cacheWrite, usage.cacheWriteTokens),
49	  );
50	}
51	
52	export function creditsFor(micros: number): number {
53	  // Zero measured cost means zero credits. The floor below exists so a real
54	  // but tiny cost never rounds down to free — it must NOT turn a build with no
55	  // metered spend at all into a 1-credit charge.
56	  //
57	  // This is not hypothetical: on the SDK engine a build whose telemetry is
58	  // missing reports 0 tokens and 0 micros (see meterUsage in lib/agent-sdk.ts),
59	  // and every one of those was being billed a credit for spend that provably
60	  // did not happen — inside the one module whose stated purpose is never doing
61	  // that. Found 2026-08-22 in a real ledger row.
62	  if (micros <= 0) return 0;
63	  return Math.max(1, Math.ceil(micros / MICROS_PER_CREDIT));
64	}
65	
66	// ── Rule 4: the repair pass is on us ──────────────────────────────────────
67	//
68	// A run can take more than one attempt (MAX_BUILD_ATTEMPTS in
69	// app/api/generate/route.ts). Attempt 1 is what the customer asked for. Every
70	// attempt after it exists only because attempt 1 produced code that did not
71	// compile — the model's mistake, fed back to the model with a fixed repair
72	// prompt the customer never sees and cannot steer.
73	//
74	// Until this function existed the route summed the tokens of every attempt and
75	// charged the lot, so a run that broke, self-repaired and then succeeded cost
76	// roughly double a clean one. Rule 3 already says a build that never compiles
77	// is free; charging double for one that took two goes to get there contradicts
78	// the same principle one step later.
79	//
80	// WHY WE BILL ATTEMPT 1 AND NOT THE SUCCESSFUL ATTEMPT:
81	//   - Attempt 1 is the only pass whose content the customer chose. The repair
82	//     pass is driven entirely by our build error.
83	//   - Attempt 1's metered cost IS "what a clean run of this request would have
84	//     cost" — a real measurement, not a cap pulled from a constant. Billing
85	//     the successful attempt instead would sometimes charge MORE than a clean
86	//     run, because a repair pass re-reads a project that attempt 1 just grew.
87	//   - It makes the charge for a repaired run indistinguishable from the charge
88	//     for a clean one. That is the promise, stated as arithmetic.
89	//
90	// The waived tokens were really spent, and `costMicros` below still reports
91	// every one of them so /admin and /admin/analytics see the true cost. Only
92	// `credits` — what we CHARGE — is reduced.
93	
94	const NO_USAGE: Usage = {
95	  inputTokens: 0,
96	  outputTokens: 0,
97	  cacheReadTokens: 0,
98	  cacheWriteTokens: 0,
99	};
100	
101	export function sumUsage(attempts: readonly Usage[]): Usage {
102	  return attempts.reduce<Usage>(
103	    (acc, u) => ({
104	      inputTokens: acc.inputTokens + u.inputTokens,
105	      outputTokens: acc.outputTokens + u.outputTokens,
106	      cacheReadTokens: acc.cacheReadTokens + u.cacheReadTokens,
107	      cacheWriteTokens: acc.cacheWriteTokens + u.cacheWriteTokens,
108	    }),
109	    NO_USAGE,
110	  );
111	}
112	
113	export type BuildSettlement = {
114	  /** TRUE spend for the whole run, every attempt included. Goes on Build.costMicros. */
115	  costMicros: number;
116	  /** Spend on the one billable attempt. */
117	  billedMicros: number;
118	  /** Spend absorbed because it went on repairing our own broken output. */
119	  waivedMicros: number;
120	  /** Credits to actually charge. Goes on Build.creditsCharged and the ledger. */
121	  credits: number;
122	  /** Credits the whole-run rule would have charged on top of `credits`. */
123	  waivedCredits: number;
124	  /** True when a repair happened AND it saved the customer at least one credit. */
125	  repairWaived: boolean;
126	};
127	
128	/**
129	 * Turn one run's per-attempt usage into what we record and what we charge.
130	 *
131	 * `attempts` is in the order the attempts ran; `attempts[0]` is the customer's
132	 * request and is the only billable one. An empty array (no telemetry at all)
133	 * settles to zero, same as any unmetered build — see creditsFor.
134	 */
135	export function settleBuild(model: string, attempts: readonly Usage[]): BuildSettlement {
136	  const total = costMicros(model, sumUsage(attempts));
137	  const billed = costMicros(model, attempts[0] ?? NO_USAGE);
138	  const credits = creditsFor(billed);
139	  // Measured against what the pre-rule-4 behaviour would have charged, so the
140	  // number we show the customer is the saving they actually made, already
141	  // rounded the same way their charge is.
142	  const waivedCredits = Math.max(0, creditsFor(total) - credits);
143	  return {
144	    costMicros: total,
145	    billedMicros: billed,
146	    waivedMicros: Math.max(0, total - billed),
147	    credits,
148	    waivedCredits,
149	    repairWaived: attempts.length > 1 && waivedCredits > 0,
150	  };
151	}
152	
153	export async function getBalance(userId: string): Promise<number> {
154	  const latest = await db.creditLedger.findFirst({
155	    where: { userId },
156	    orderBy: { createdAt: "desc" },
157	  });
158	  return latest?.balanceAfter ?? 0;
159	}
160	
161	export async function grantCredits(userId: string, amount: number, reason: string) {
162	  const balance = await getBalance(userId);
163	  return db.creditLedger.create({
164	    data: { userId, delta: amount, reason, balanceAfter: balance + amount },
165	  });
166	}
167	
168	/**
169	 * Charge for a SUCCESSFUL build. Never call this on a failed build — the whole
170	 * promise to the customer is that broken output is free. `credits` must be the
171	 * settled figure from settleBuild, not the run's raw cost.
172	 *
173	 * The reason string stays exactly "build", including when rule 4 waived a
174	 * repair. That is deliberate, not an oversight. `describeReason` in
175	 * app/dashboard/billing/ledger.ts is a closed allowlist that never echoes
176	 * `reason` back to a customer (it can carry a Stripe session id or an account
177	 * hash), so ANY new string here — "build:repair_waived" or otherwise — falls
178	 * through to its unknown branch and downgrades the statement row from "Site
179	 * build" to a bare "Credits used". Encoding the waiver in `reason` would make
180	 * the statement worse, not better.
181	 *
182	 * The statement does not need an encoding: it already joins CreditLedger.build,
183	 * and the truth is on that row. Build.repairAttempts > 0 together with
184	 * costMicros > creditsCharged * MICROS_PER_CREDIT is exactly "this run was
185	 * repaired and we absorbed it". Surfacing it is two changes outside this
186	 * module: add `repairAttempts`, `costMicros`, `creditsCharged` to the
187	 * `build: { select: … }` in app/dashboard/billing/page.tsx, and render a second
188	 * line on those rows.
189	 */
190	export async function chargeForBuild(userId: string, buildId: string, credits: number) {
191	  const balance = await getBalance(userId);
192	  await db.creditLedger.create({
193	    data: {
194	      userId,
195	      delta: -credits,
196	      reason: "build",
197	      buildId,
198	      balanceAfter: balance - credits,
199	    },
200	  });
201	  return balance - credits;
202	}
203	
204	/**
205	 * Pre-flight estimate shown BEFORE the user spends anything. Deliberately a
206	 * range derived from observed build sizes, not a fake precise number.
207	 *
208	 * Numbers corrected 2026-08-21. The previous 8-30 / 3-15 ranges predated the
209	 * costMicros fix and understated real spend by roughly an order of magnitude —
210	 * on a product whose headline promise is no bill shock, an estimate that low
211	 * is worse than showing nothing.
212	 *
213	 * The honest state of our evidence: measured builds have come in at ~144
214	 * credits (2026-08-17) and ~472 credits (2026-08-21, a first build of a
215	 * tradesman site via the eval harness). That is a 3x spread across two
216	 * samples, so the range below is deliberately wide rather than falsely
217	 * precise, and skews high — quoting low and charging high is the exact
218	 * failure this whole module exists to prevent.
219	 *
220	 * REPLACE THIS with real percentiles once the eval harness has run a full
221	 * sweep (scripts/eval). Two data points is not a distribution.
222	 */
223	export function estimateCredits(kind: "create" | "edit"): { low: number; high: number } {
224	  return kind === "create" ? { low: 120, high: 550 } : { low: 60, high: 300 };
225	}
226	
227	/**
228	 * Fallback when a user has no build history to average. Sits near the upper
229	 * of our two measurements on purpose: this drives "about N more builds", and
230	 * over-promising remaining builds is how someone hits zero mid-build.
231	 */
232	const TYPICAL_BUILD_CREDITS = 400;
233	
234	/**
235	 * What a build actually costs THIS user, averaged over their recent successful
236	 * builds. Personal history beats a global constant: someone building one-page
237	 * sites and someone building ten-page sites deserve different answers to
238	 * "how many builds do I have left?".
239	 */
240	export async function averageBuildCredits(userId: string): Promise<number> {
241	  const recent = await db.build.findMany({
242	    where: { project: { userId }, status: "SUCCEEDED", creditsCharged: { gt: 0 } },
243	    orderBy: { createdAt: "desc" },
244	    take: 10,
245	    select: { creditsCharged: true },
246	  });
247	  if (recent.length === 0) return TYPICAL_BUILD_CREDITS;
248	  const total = recent.reduce((sum, b) => sum + b.creditsCharged, 0);
249	  return Math.max(1, Math.round(total / recent.length));
250	}
251	
252	// ── Self-imposed spend cap ────────────────────────────────────────────────
253	// Point 4 of the anti-bill-shock contract. The three rules above stop us from
254	// OVERCHARGING for a given build; none of them stop a user from running fifty
255	// builds in an afternoon and being genuinely shocked by the total. A ceiling
256	// the user sets themselves is the honest answer, and it is the one guard a
257	// competitor's $607-against-a-$25-plan incident would have needed.
258	//
259	// Rolling 30 days, not calendar month, so there is no "reset day" to game and
260	// no cliff where a cap silently stops protecting someone mid-month.
261	
262	const CAP_WINDOW_DAYS = 30;
263	
264	export type SpendCapStatus = {
265	  /** NULL when the user has set no cap. */
266	  cap: number | null;
267	  spent: number;
268	  /** Credits still available under the cap; Infinity when uncapped. */
269	  remaining: number;
270	  reached: boolean;
271	};
272	
273	/** Credits spent on builds in the rolling window. Grants are excluded. */
274	export async function spentInWindow(userId: string): Promise<number> {
275	  const since = new Date(Date.now() - CAP_WINDOW_DAYS * 24 * 60 * 60 * 1000);
276	  const { _sum } = await db.creditLedger.aggregate({
277	    where: { userId, createdAt: { gte: since }, delta: { lt: 0 } },
278	    _sum: { delta: true },
279	  });
280	  // Deltas are negative for spend; report it as a positive number.
281	  return Math.abs(_sum.delta ?? 0);
282	}
283	
284	export async function getSpendCapStatus(userId: string): Promise<SpendCapStatus> {
285	  const user = await db.user.findUnique({
286	    where: { id: userId },
287	    select: { spendCapCredits: true },
288	  });
289	  const cap = user?.spendCapCredits ?? null;
290	
291	  if (cap === null) {
292	    return { cap: null, spent: 0, remaining: Infinity, reached: false };
293	  }
294	
295	  const spent = await spentInWindow(userId);
296	  return { cap, spent, remaining: Math.max(0, cap - spent), reached: spent >= cap };
297	}
