310	function complement(hex: string): string {
311	  const [r, g, b] = channels(hex).map((c) => c / 255);
312	  const max = Math.max(r, g, b);
313	  const min = Math.min(r, g, b);
314	  const l = (max + min) / 2;
315	  const d = max - min;
316	  const s = d === 0 ? 0 : d / (1 - Math.abs(2 * l - 1));
317	  let h = 0;
318	  if (d !== 0) {
319	    if (max === r) h = ((g - b) / d) % 6;
320	    else if (max === g) h = (b - r) / d + 2;
321	    else h = (r - g) / d + 4;
322	  }
323	  h = (h * 60 + 180 + 360) % 360;
324	  return hslToHex(h, s, l);
325	}
326	
327	function hslToHex(h: number, s: number, l: number): string {
328	  const c = (1 - Math.abs(2 * l - 1)) * s;
329	  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
330	  const m = l - c / 2;
331	  const seg = Math.floor(h / 60) % 6;
332	  const rgb: [number, number, number][] = [
333	    [c, x, 0],
334	    [x, c, 0],
335	    [0, c, x],
336	    [0, x, c],
337	    [x, 0, c],
338	    [c, 0, x],
339	  ];
340	  const [r, g, b] = rgb[seg];
341	  return toHex((r + m) * 255, (g + m) * 255, (b + m) * 255);
342	}
