import { db } from "@/lib/db";
import { BRAND_FILE_KIND, BRAND_FILE_PATH, parseStoredBrandKit } from "@/lib/brand-kit";
import type { WebsiteCardProject, WebsiteCover } from "@/components/app/WebsiteCard";

/* Everything both /dashboard and /dashboard/websites need to describe a site,
   in ONE place, because the two pages render the same card and must never
   disagree about what a site's state is.

   This module is deliberately server-only-ish (it imports lib/db) but carries
   no "use client" directive and exports plain functions, so a Server Component
   can call it. WebsiteCard is the client half and only ever receives the plain
   objects produced here — no Date, no Prisma model, nothing that would have to
   be re-derived in the browser. */

/**
 * How long a `Build.status = "RUNNING"` row is still believed.
 *
 * There is no cleanup for an abandoned build: the generate route streams over
 * SSE, and a dropped connection, a crashed process or a redeploy leaves the row
 * RUNNING forever. Rendering that as "Building…" would mean a site that claims
 * to be working on something for the rest of its life.
 *
 * The cut-off is not a guess. app/api/generate/route.ts sets
 * `export const maxDuration = 300` — the platform itself kills the request at
 * five minutes, so no build can legitimately still be running after that. This
 * is double it, which leaves room for clock skew and a slow final write while
 * still collapsing an abandoned row to "not building" within ten minutes.
 */
export const BUILD_STALE_MS = 10 * 60 * 1000;

/** Minutes, for the sentence the UI shows about the rule above. */
export const BUILD_STALE_MINUTES = BUILD_STALE_MS / 60_000;

/** Matches the constant in app/api/projects/[id]/publish/route.ts. */
const SITES_BASE = process.env.KODELY_SITES_BASE ?? "kodely.site";

// ── Dates ──────────────────────────────────────────────────────────────────
// Formatted on the SERVER and passed down as strings. A client component that
// formatted these itself would either disagree with the server HTML at
// hydration (relative times move) or depend on the visitor's locale, which
// differs from the server's. One string, computed once, is neither.

const ABSOLUTE = new Intl.DateTimeFormat("en-GB", {
  day: "numeric",
  month: "short",
  year: "numeric",
  timeZone: "UTC",
});

export function formatDate(value: Date): string {
  return ABSOLUTE.format(value);
}

/** "3 minutes ago" … then absolute once it stops being a useful relative. */
export function formatRelative(value: Date, now: number = Date.now()): string {
  const seconds = Math.round((now - value.getTime()) / 1000);
  if (seconds < 45) return "just now";
  const minutes = Math.round(seconds / 60);
  if (minutes < 60) return `${minutes} ${minutes === 1 ? "minute" : "minutes"} ago`;
  const hours = Math.round(minutes / 60);
  if (hours < 24) return `${hours} ${hours === 1 ? "hour" : "hours"} ago`;
  const days = Math.round(hours / 24);
  if (days < 30) return `${days} ${days === 1 ? "day" : "days"} ago`;
  return ABSOLUTE.format(value);
}

// ── Generated covers ───────────────────────────────────────────────────────
//
// NOTHING IN THIS PRODUCT CAPTURES A SCREENSHOT. There is no thumbnail column,
// no headless browser, no image storage. So a card cannot show what a site
// looks like, and must not pretend to.
//
// What it CAN show is the site's own identity. If the project has a brand kit
// (lib/brand-kit.ts, stored as a ProjectFile with kind "brand") those are the
// real colours the generated site is painted with, and the cover is genuinely
// derived from the thing it represents. Without one, the cover falls back to a
// palette chosen deterministically from the slug — stable forever, distinct
// between neighbours in a grid, and obviously a generated mark rather than a
// picture of a page.

/** Fallback covers. Curated pairs, not random hues, so a grid stays coherent. */
const COVER_PALETTES: readonly (readonly [string, string])[] = [
  ["#f72570", "#a33dff"],
  ["#0ea5e9", "#2563eb"],
  ["#14b8a6", "#0e7490"],
  ["#f97316", "#dc2626"],
  ["#6366f1", "#a855f7"],
  ["#22d3ee", "#7c3aed"],
  ["#84cc16", "#0d8f5b"],
  ["#fb7185", "#f59e0b"],
];

/** FNV-1a. Small, dependency-free, and stable across processes and deploys. */
function hash(input: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < input.length; i++) {
    h ^= input.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h >>> 0;
}

export function coverFor(
  slug: string,
  brand: { primary: string; secondary: string } | null,
): WebsiteCover {
  if (brand) return { from: brand.primary, to: brand.secondary, source: "brand" };
  const [from, to] = COVER_PALETTES[hash(slug) % COVER_PALETTES.length];
  return { from, to, source: "slug" };
}

/** One or two letters from the site's own name. Same rule as Avatar. */
export function monogramFor(name: string): string {
  const parts = name.trim().split(/[\s._-]+/).filter(Boolean);
  if (parts.length === 0) return "?";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[1][0]).toUpperCase();
}

// ── Loading ────────────────────────────────────────────────────────────────

/**
 * Every site the customer owns, in the exact shape the card renders.
 *
 * Four reads, one round of parallelism, all scoped to project ids this user
 * owns (the first query is the authorization boundary; the rest filter by its
 * output). None of them is per-card — an N+1 over a site list is how a
 * dashboard becomes slow the moment someone is actually using the product.
 */
export async function loadWebsites(
  userId: string,
  opts: { take?: number } = {},
): Promise<WebsiteCardProject[]> {
  const projects = await db.project.findMany({
    where: { userId },
    orderBy: { updatedAt: "desc" },
    ...(opts.take != null ? { take: opts.take } : {}),
    select: { id: true, name: true, slug: true, publishedAt: true, updatedAt: true, createdAt: true },
  });
  if (projects.length === 0) return [];

  const ids = projects.map((p) => p.id);

  const [brandRows, buildableRows, runningRows] = await Promise.all([
    db.projectFile.findMany({
      where: { projectId: { in: ids }, kind: BRAND_FILE_KIND, path: BRAND_FILE_PATH },
      select: { projectId: true, content: true },
    }),
    // A publish copies the DRAFT `kind: "build"` tree onto the published rows
    // (app/api/projects/[id]/publish/route.ts). No such rows means the publish
    // call would 400 — so the menu greys the action instead of offering it.
    db.projectFile.findMany({
      where: { projectId: { in: ids }, published: false, kind: "build" },
      select: { projectId: true },
      distinct: ["projectId"],
    }),
    // Only builds young enough to still be believable. See BUILD_STALE_MS.
    db.build.findMany({
      where: {
        projectId: { in: ids },
        status: "RUNNING",
        createdAt: { gte: new Date(Date.now() - BUILD_STALE_MS) },
      },
      select: { projectId: true },
      distinct: ["projectId"],
    }),
  ]);

  const brands = new Map<string, { primary: string; secondary: string }>();
  for (const row of brandRows) {
    const kit = parseStoredBrandKit(row.content);
    if (kit) brands.set(row.projectId, { primary: kit.palette.primary, secondary: kit.palette.secondary });
  }
  const publishable = new Set(buildableRows.map((r) => r.projectId));
  const building = new Set(runningRows.map((r) => r.projectId));

  const now = Date.now();
  return projects.map((p) => ({
    id: p.id,
    name: p.name,
    slug: p.slug,
    liveUrl: `https://${p.slug}.${SITES_BASE}`,
    liveLabel: `${p.slug}.${SITES_BASE}`,
    published: p.publishedAt !== null,
    building: building.has(p.id),
    publishable: publishable.has(p.id),
    monogram: monogramFor(p.name),
    cover: coverFor(p.slug, brands.get(p.id) ?? null),
    updatedAt: p.updatedAt.getTime(),
    updatedIso: p.updatedAt.toISOString(),
    updatedLabel: formatRelative(p.updatedAt, now),
    createdAt: p.createdAt.getTime(),
    createdIso: p.createdAt.toISOString(),
    createdLabel: formatDate(p.createdAt),
  }));
}

// ── Search params ──────────────────────────────────────────────────────────

export type ViewMode = "grid" | "list";
export type SortKey = "updated" | "created" | "name";

/**
 * The filters that can actually match something.
 *
 * "Archived" is absent and stays absent: there is no soft-delete column on
 * Project, and app/api/projects/[id]/route.ts states outright that delete is
 * irreversible with no archive. A filter that can never return a row is worse
 * than no filter, because it teaches the customer that their sites vanished.
 *
 * "Building" IS offered, but only under the staleness rule in BUILD_STALE_MS —
 * without it, one crashed SSE connection leaves a site filed under "Building"
 * permanently.
 */
export type StatusFilter = "all" | "published" | "draft" | "building";

const VIEWS: Record<ViewMode, true> = { grid: true, list: true };
const SORTS: Record<SortKey, true> = { updated: true, created: true, name: true };
const STATUSES: Record<StatusFilter, true> = {
  all: true,
  published: true,
  draft: true,
  building: true,
};

export type WebsiteParams = { view: ViewMode; sort: SortKey; status: StatusFilter; q: string };

/** First value of a possibly-repeated query parameter, or null. */
function first(raw: string | string[] | undefined): string | null {
  if (typeof raw === "string") return raw;
  if (Array.isArray(raw) && typeof raw[0] === "string") return raw[0];
  return null;
}

/**
 * `hasOwnProperty.call`, never `in`. `in` walks the prototype chain, so
 * `?view=constructor` or `?sort=toString` would pass a membership test against
 * an object literal and then index it to a function.
 */
function pick<T extends string>(table: Record<string, true>, raw: string | string[] | undefined, fallback: T): T {
  const value = first(raw);
  if (value === null) return fallback;
  return Object.prototype.hasOwnProperty.call(table, value) ? (value as T) : fallback;
}

const QUERY_MAX = 80;

export function readWebsiteParams(
  searchParams: Record<string, string | string[] | undefined>,
): WebsiteParams {
  const read = (key: string): string | string[] | undefined =>
    Object.prototype.hasOwnProperty.call(searchParams, key) ? searchParams[key] : undefined;

  return {
    view: pick<ViewMode>(VIEWS, read("view"), "grid"),
    sort: pick<SortKey>(SORTS, read("sort"), "updated"),
    status: pick<StatusFilter>(STATUSES, read("status"), "all"),
    q: (first(read("q")) ?? "").slice(0, QUERY_MAX),
  };
}

"use client";

import { useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { Archive, Copy, ExternalLink, MoreHorizontal, Pencil, Rocket, SquarePen, Trash2 } from "lucide-react";
import { api, ApiError } from "@/lib/api";
import { Badge } from "@/components/ui/Badge";
import { Button, IconButton } from "@/components/ui/Button";
import { Card } from "@/components/ui/Card";
import { Input } from "@/components/ui/Field";
import { Menu } from "@/components/ui/Menu";
import type { MenuItem } from "@/components/ui/Menu";
import { ConfirmModal, Modal } from "@/components/ui/Modal";
import { useToast } from "@/components/ui/Toast";

/* One site, as a card or as a row. Both variants are the same component on
   purpose: the grid/list toggle must not be able to show different facts or
   offer different actions depending on which way it is pointed.

   Every prop is a plain value computed on the server (see
   app/(portal)/dashboard/websites/data.ts). Nothing here re-derives state from
   a Date or a Prisma row, which is what keeps the two pages that render this
   from drifting apart — and what keeps relative timestamps from disagreeing
   with the server HTML at hydration. */

export type WebsiteCover = {
  from: string;
  to: string;
  /** "brand" = the site's real palette. "slug" = derived, no kit exists. */
  source: "brand" | "slug";
};

export type WebsiteCardProject = {
  id: string;
  name: string;
  slug: string;
  /** `https://<slug>.<sites base>` — the address a publish puts it at. */
  liveUrl: string;
  liveLabel: string;
  published: boolean;
  /** A RUNNING build young enough to still be believed. See BUILD_STALE_MS. */
  building: boolean;
  /** There is a compiled draft tree, so Publish would not 400. */
  publishable: boolean;
  monogram: string;
  cover: WebsiteCover;
  updatedAt: number;
  updatedIso: string;
  updatedLabel: string;
  createdAt: number;
  createdIso: string;
  createdLabel: string;
};

/** Matches the cap in app/api/projects/[id]/route.ts. */
const NAME_MAX = 80;

type Dialog = "none" | "rename" | "delete";

/**
 * The generated cover.
 *
 * Deliberately NOT a screenshot and deliberately not shaped like one: no
 * browser chrome, no fake page layout, no blurred rectangle standing in for
 * content. It is a coloured field with the site's initials, which reads as a
 * generated mark the way a contact's initials disc does. Nothing captures a
 * screenshot in this product, so anything that resembled one would be a lie.
 *
 * Gradient ids are derived from the project's cuid rather than useId(): React
 * 19's generated ids contain characters that are awkward inside `url(#…)`, and
 * a cuid is already unique and URL-safe.
 */
function Cover({ project, className }: { project: WebsiteCardProject; className: string }) {
  const gradientId = `wc-g-${project.id}`;
  const dotsId = `wc-d-${project.id}`;
  return (
    <svg
      viewBox="0 0 320 180"
      preserveAspectRatio="xMidYMid slice"
      role="img"
      aria-label={`${project.name} — generated cover`}
      className={className}
    >
      <defs>
        <linearGradient id={gradientId} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor={project.cover.from} />
          <stop offset="100%" stopColor={project.cover.to} />
        </linearGradient>
        <pattern id={dotsId} width="14" height="14" patternUnits="userSpaceOnUse">
          <circle cx="2" cy="2" r="1" fill="rgba(255,255,255,0.22)" />
        </pattern>
      </defs>
      <rect width="320" height="180" fill={`url(#${gradientId})`} />
      <rect width="320" height="180" fill={`url(#${dotsId})`} />
      <text
        x="160"
        y="92"
        textAnchor="middle"
        dominantBaseline="central"
        fill="rgba(255,255,255,0.94)"
        fontSize="58"
        fontWeight="600"
        letterSpacing="-2"
        fontFamily="inherit"
      >
        {project.monogram}
      </text>
    </svg>
  );
}

function StatusBadge({ project }: { project: WebsiteCardProject }) {
  if (project.building) {
    return (
      <Badge tone="info" dot pulse>
        Building
      </Badge>
    );
  }
  return project.published ? (
    <Badge tone="ok" dot>
      Published
    </Badge>
  ) : (
    <Badge tone="neutral" dot>
      Draft
    </Badge>
  );
}

export function WebsiteCard({
  project,
  variant = "grid",
}: {
  project: WebsiteCardProject;
  variant?: "grid" | "list";
}) {
  const router = useRouter();
  const toast = useToast();

  const [dialog, setDialog] = useState<Dialog>("none");
  const [busy, setBusy] = useState(false);
  const [draftName, setDraftName] = useState(project.name);
  const [renameError, setRenameError] = useState<string | null>(null);

  async function run(label: string, fn: () => Promise<void>) {
    setBusy(true);
    try {
      await fn();
    } catch (err) {
      toast({
        tone: "danger",
        message: err instanceof ApiError ? err.message : `Couldn't ${label}. Try again.`,
      });
    } finally {
      setBusy(false);
    }
  }

  const trimmed = draftName.trim();

  function saveRename() {
    if (trimmed.length === 0) {
      setRenameError("A name is required.");
      return;
    }
    if (trimmed === project.name) {
      setDialog("none");
      return;
    }
    setRenameError(null);
    void run("rename this site", async () => {
      await api(`/api/projects/${project.id}`, {
        method: "PATCH",
        body: JSON.stringify({ name: trimmed }),
      });
      setDialog("none");
      toast({ tone: "ok", message: `Renamed to “${trimmed}”.` });
      router.refresh();
    });
  }

  function duplicate() {
    void run("duplicate this site", async () => {
      const { project: copy } = await api<{ project: { id: string; name: string } }>(
        `/api/projects/${project.id}`,
        { method: "POST" },
      );
      toast({
        tone: "ok",
        message: `Copied to “${copy.name}”. Nothing was generated, so this cost no credits.`,
        action: { label: "Open", onClick: () => router.push(`/projects/${copy.id}`) },
      });
      router.refresh();
    });
  }

  function publish() {
    void run("publish this site", async () => {
      const { url } = await api<{ url: string }>(`/api/projects/${project.id}/publish`, {
        method: "POST",
      });
      toast({
        tone: "ok",
        message: project.published ? "Republished — the live site is updated." : "Published. Your site is live.",
        action: { label: "Visit", onClick: () => window.open(url, "_blank", "noopener,noreferrer") },
      });
      router.refresh();
    });
  }

  function confirmDelete() {
    void run("delete this site", async () => {
      await api(`/api/projects/${project.id}`, { method: "DELETE" });
      setDialog("none");
      toast({ tone: "ok", message: `“${project.name}” was deleted.` });
      router.refresh();
    });
  }

  const items: MenuItem[] = [
    {
      kind: "item",
      label: "Open live site",
      icon: <ExternalLink className="size-3.5" />,
      onSelect: () => window.open(project.liveUrl, "_blank", "noopener,noreferrer"),
      unavailableReason: project.published ? undefined : "Not published",
    },
    {
      kind: "item",
      label: "Edit in the builder",
      icon: <SquarePen className="size-3.5" />,
      href: `/projects/${project.id}`,
    },
    { kind: "separator" },
    {
      kind: "item",
      label: "Rename",
      icon: <Pencil className="size-3.5" />,
      onSelect: () => {
        setDraftName(project.name);
        setRenameError(null);
        setDialog("rename");
      },
    },
    {
      kind: "item",
      label: "Duplicate",
      icon: <Copy className="size-3.5" />,
      onSelect: duplicate,
    },
    {
      kind: "item",
      label: project.published ? "Republish" : "Publish",
      icon: <Rocket className="size-3.5" />,
      onSelect: publish,
      unavailableReason: project.publishable ? undefined : "Nothing built yet",
    },
    { kind: "separator" },
    {
      // Kept visible rather than hidden: people look for it. There is no
      // soft-delete column on Project and no route that could set one, so the
      // honest answer is to say so where the customer goes looking.
      kind: "item",
      label: "Archive",
      icon: <Archive className="size-3.5" />,
      unavailableReason: "Doesn’t exist yet",
    },
    {
      kind: "item",
      label: "Delete…",
      icon: <Trash2 className="size-3.5" />,
      danger: true,
      onSelect: () => setDialog("delete"),
    },
  ];

  const menu = (
    <Menu
      align="end"
      className="relative z-10 shrink-0"
      items={items}
      trigger={(props) => (
        <IconButton {...props} type="button" size="sm" label={`Actions for ${project.name}`} disabled={busy}>
          <MoreHorizontal className="size-4" />
        </IconButton>
      )}
    />
  );

  const address = project.published ? (
    <a
      href={project.liveUrl}
      target="_blank"
      rel="noopener noreferrer"
      className="k-focus relative z-10 truncate rounded-xs text-[0.8125rem] text-ink-2 underline-offset-2 hover:text-brand hover:underline"
    >
      {project.liveLabel}
    </a>
  ) : (
    <span className="truncate text-[0.8125rem] text-ink-3" title={`${project.liveLabel} once published`}>
      {project.liveLabel}
    </span>
  );

  const dialogs = (
    <>
      {dialog === "rename" && (
        <Modal
          open
          onClose={() => setDialog("none")}
          title="Rename site"
          description={`The address stays ${project.liveLabel} — renaming never changes a site’s URL.`}
          size="sm"
          footer={
            <>
              <Button variant="ghost" size="sm" onClick={() => setDialog("none")} disabled={busy}>
                Cancel
              </Button>
              <Button variant="secondary" size="sm" onClick={saveRename} loading={busy}>
                Save name
              </Button>
            </>
          }
        >
          <Input
            label="Site name"
            autoFocus
            value={draftName}
            maxLength={NAME_MAX}
            disabled={busy}
            error={renameError ?? undefined}
            onChange={(e) => setDraftName(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault();
                saveRename();
              }
            }}
          />
        </Modal>
      )}

      {dialog === "delete" && (
        <ConfirmModal
          open
          busy={busy}
          onClose={() => setDialog("none")}
          onConfirm={confirmDelete}
          title={`Delete ${project.name}?`}
          confirmLabel="Delete site"
          body={
            <>
              <p>
                This deletes the site, its files, its chat history and its build history. There is
                no archive and no undo —{" "}
                <strong className="font-medium text-ink">it cannot be recovered.</strong>
              </p>
              {project.published && (
                <p className="mt-2 text-danger">
                  {project.liveLabel} is live. Deleting takes it offline immediately, and the
                  address is released — it cannot be reclaimed.
                </p>
              )}
              <p className="mt-2 text-xs text-ink-3">
                Your credit balance and billing history are unaffected.
              </p>
            </>
          }
        />
      )}
    </>
  );

  // ── List row ─────────────────────────────────────────────────────────────
  if (variant === "list") {
    return (
      <div className="relative flex items-center gap-3 px-3 py-2.5 transition-colors duration-[var(--t-1)] hover:bg-surface-2 sm:gap-4 sm:px-4">
        <Cover project={project} className="h-10 w-16 shrink-0 rounded-sm" />

        <div className="min-w-0 flex-1">
          <div className="flex min-w-0 items-center gap-2">
            <Link
              href={`/projects/${project.id}`}
              className="k-focus truncate rounded-xs text-sm font-medium text-ink after:absolute after:inset-0 after:content-['']"
            >
              {project.name}
            </Link>
            <StatusBadge project={project} />
          </div>
          <div className="mt-0.5 flex min-w-0 items-center gap-2">{address}</div>
        </div>

        <div className="k-num hidden w-36 shrink-0 text-right text-xs text-ink-2 md:block">
          <time dateTime={project.updatedIso}>{project.updatedLabel}</time>
          <span className="sr-only"> — last updated</span>
        </div>
        <div className="k-num hidden w-28 shrink-0 text-right text-xs text-ink-3 lg:block">
          <time dateTime={project.createdIso}>{project.createdLabel}</time>
          <span className="sr-only"> — created</span>
        </div>

        {menu}
        {dialogs}
      </div>
    );
  }

  // ── Grid card ────────────────────────────────────────────────────────────
  return (
    <Card interactive padded={false} className="relative flex flex-col overflow-hidden">
      <Cover project={project} className="aspect-[16/9] w-full" />

      <div className="flex flex-1 flex-col gap-2 p-4">
        <div className="flex items-start justify-between gap-2">
          <Link
            href={`/projects/${project.id}`}
            className="k-focus min-w-0 rounded-xs text-sm font-medium text-ink after:absolute after:inset-0 after:content-['']"
          >
            <span className="line-clamp-2">{project.name}</span>
          </Link>
          {menu}
        </div>

        <div className="flex min-w-0 items-center gap-2">
          <StatusBadge project={project} />
          {address}
        </div>

        <dl className="k-num mt-auto grid grid-cols-2 gap-x-3 border-t border-hair pt-3 text-xs">
          <div className="min-w-0">
            <dt className="text-ink-3">Updated</dt>
            <dd className="truncate text-ink-2">
              <time dateTime={project.updatedIso}>{project.updatedLabel}</time>
            </dd>
          </div>
          <div className="min-w-0 text-right">
            <dt className="text-ink-3">Created</dt>
            <dd className="truncate text-ink-2">
              <time dateTime={project.createdIso}>{project.createdLabel}</time>
            </dd>
          </div>
        </dl>
      </div>

      {dialogs}
    </Card>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Plus } from "lucide-react";
import { api, ApiError } from "@/lib/api";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Field";
import { Modal } from "@/components/ui/Modal";
import type { ButtonSize, ButtonVariant } from "@/components/ui/Button";

/* Start a blank site.
 *
 * This used to be `window.prompt()`. Three things were wrong with that beyond
 * the look: it is unstyled and unbrandable, it is blocked outright in some
 * browsers and embedded webviews (in which case the button silently did
 * nothing), and it cannot show the one thing the customer needs at that moment
 * — that the name they type is a label and NOT the site's address.
 *
 * Deliberately a SECONDARY action everywhere it appears. The primary path is
 * "Create Website", which goes to the guided flow; this is the escape hatch for
 * someone who just wants an empty project open in the builder. The default
 * label stays "New site" because the first-run checklist
 * (components/onboarding/FirstRunPanel.tsx) tells people to look for that
 * wording. */

/** Matches the cap in app/api/projects/route.ts. */
const NAME_MAX = 80;
const DEFAULT_NAME = "My site";

export default function NewProjectButton({
  label = "New site",
  variant = "secondary",
  size = "md",
}: {
  label?: string;
  variant?: ButtonVariant;
  size?: ButtonSize;
}) {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [name, setName] = useState(DEFAULT_NAME);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  function close() {
    if (busy) return;
    setOpen(false);
    setError(null);
  }

  function create() {
    const trimmed = name.trim().slice(0, NAME_MAX).trim();
    if (!trimmed) {
      setError("Give the site a name — you can change it later.");
      return;
    }
    setBusy(true);
    setError(null);
    void (async () => {
      try {
        const { project } = await api<{ project: { id: string } }>("/api/projects", {
          method: "POST",
          body: JSON.stringify({ name: trimmed }),
        });
        // No setBusy(false) on the happy path: the button must stay disabled
        // while the route transition is in flight, or a second click creates a
        // second project.
        router.push(`/projects/${project.id}`);
      } catch (err) {
        setError(err instanceof ApiError ? err.message : "Couldn't create the site. Try again.");
        setBusy(false);
      }
    })();
  }

  return (
    <>
      <Button
        variant={variant}
        size={size}
        icon={<Plus className="size-4" />}
        onClick={() => {
          setName(DEFAULT_NAME);
          setError(null);
          setOpen(true);
        }}
      >
        {label}
      </Button>

      {open && (
        <Modal
          open
          onClose={close}
          title="Name your site"
          description="Just a label for your dashboard. You describe what to build in the next step."
          size="sm"
          footer={
            <>
              <Button variant="ghost" size="sm" onClick={close} disabled={busy}>
                Cancel
              </Button>
              <Button variant="secondary" size="sm" onClick={create} loading={busy}>
                Create site
              </Button>
            </>
          }
        >
          <Input
            label="Site name"
            autoFocus
            value={name}
            maxLength={NAME_MAX}
            disabled={busy}
            error={error ?? undefined}
            hint="Renaming later never changes the site’s address."
            onChange={(e) => setName(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault();
                create();
              }
            }}
          />
        </Modal>
      )}
    </>
  );
}

